}
.todo-history-date-v146 {
  color: #788c9b;
  font-size: .68rem;
  font-weight: 850;
  white-space: nowrap;
}
.todo-history-search-only-v146 {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  clip-path: inset(50%) !important;
